def audit_ownerless_rows(apps, schema_editor):
    """Report the stored rows which no owner holds, as the work queue arrives.

    The single-owner constraint of #1263 keeps the both-null shape of these
    rows readable on purpose: rows written before any flow named an owner
    are unknown history, and silently reassigning or dropping them would
    destroy what little the storage still knows about them. What an
    operator can do with unknown history is decide with the report in hand,
    so the moment the schema learns about owners, the number of rows it
    cannot attribute is said out loud once.
    """
    TemporaryMdMetadataFile = apps.get_model(
        "registry", "TemporaryMdMetadataFile")
    ownerless = TemporaryMdMetadataFile.objects.filter(
        job__isnull=True, background_process__isnull=True).count()
    if ownerless:
        logger.warning(
            "%s TemporaryMdMetadataFile row(s) have neither a harvesting job "
            "nor a background process - they predate the owner-carrying "
            "layout of #1263 and stay readable as unknown history; see "
            "registry.models.harvest.TemporaryMdMetadataFile.", ownerless)


